import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"Packaging & Distribution","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/packaging.md","filePath":"dev-guide/packaging.md","lastUpdated":1787982919000}'),n={name:"dev-guide/packaging.md"};function l(p,s,r,o,h,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="packaging-distribution" tabindex="-1">Packaging &amp; Distribution <a class="header-anchor" href="#packaging-distribution" aria-label="Permalink to &quot;Packaging &amp; Distribution&quot;">​</a></h1><p>This chapter details directory conventions for plugin assemblies, bundling third-party dependencies, embedding i18n JSON resources, and automated build deployment.</p><h2 id="_1-plugin-assembly-directory-structure" tabindex="-1">1. Plugin Assembly Directory Structure <a class="header-anchor" href="#_1-plugin-assembly-directory-structure" aria-label="Permalink to &quot;1. Plugin Assembly Directory Structure&quot;">​</a></h2><p>Lertaro recursively scans the <code>Plugins\\</code> folder located in the application root directory. To maintain clean isolation and avoid dependency conflicts across different plugins, place each plugin into its own dedicated subfolder:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── MyCustomPlugin.dll           (Main Plugin Assembly)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll       (Managed Third-Party Dependency)</span></span>
<span class="line"><span>        └── x64/</span></span>
<span class="line"><span>            └── NativeLibrary.dll        (Native C/C++ Dynamic Link Library)</span></span></code></pre></div><ul><li><strong>Automatic Dependency Probing</strong>: When Lertaro loads the primary DLL via <code>Assembly.LoadFrom</code>, the .NET runtime automatically probes the plugin&#39;s folder for adjacent dependencies without cross-contaminating other plugins.</li><li><strong>Native File Toleration</strong>: When non-.NET native binaries (e.g. <code>e_sqlite3.dll</code>) are encountered, the loader safely logs them at <code>Debug</code> level without throwing false positive <code>Error</code> alerts.</li></ul><h2 id="_2-automated-postbuild-copy-configuration" tabindex="-1">2. Automated PostBuild Copy Configuration <a class="header-anchor" href="#_2-automated-postbuild-copy-configuration" aria-label="Permalink to &quot;2. Automated PostBuild Copy Configuration&quot;">​</a></h2><p>Add a <code>PostBuild</code> MSBuild target to your plugin&#39;s <code>.csproj</code> to automatically deploy output files into the Lertaro App debugging directory upon every successful build:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PluginOutputFiles</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)**\\*.*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@(PluginOutputFiles)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\$(TargetName)\\%(RecursiveDir)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="_3-embedding-localization-resources" tabindex="-1">3. Embedding Localization Resources <a class="header-anchor" href="#_3-embedding-localization-resources" aria-label="Permalink to &quot;3. Embedding Localization Resources&quot;">​</a></h2><p>If your plugin implements the <a href="./sdk/ui-extensions.html#itranslationprovider"><code>ITranslationProvider</code></a> interface, embed your translation JSON files directly as <strong>Embedded Resources</strong> to prevent missing language files:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Organize files using the <code>Resources/Translations/{CultureName}/{TypeName}.json</code> hierarchy (e.g. <code>zh-CN/MyCustomPlugin.json</code>, <code>en-US/MyCustomPlugin.json</code>). Calling <code>TranslationService.LoadEmbeddedTranslations</code> parses the appropriate file dynamically based on the active UI language.</p><h2 id="_4-versioning-metadata" tabindex="-1">4. Versioning &amp; Metadata <a class="header-anchor" href="#_4-versioning-metadata" aria-label="Permalink to &quot;4. Versioning &amp; Metadata&quot;">​</a></h2><p>Define assembly version numbers and descriptions inside your <code>.csproj</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;High-performance search source and context action extension plugin.&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This version and description string will be presented automatically inside the <strong>Settings → Plugins</strong> card.</p><h2 id="_5-release-build-architecture-artifacts" tabindex="-1">5. Release Build &amp; Architecture Artifacts <a class="header-anchor" href="#_5-release-build-architecture-artifacts" aria-label="Permalink to &quot;5. Release Build &amp; Architecture Artifacts&quot;">​</a></h2><p>Run <code>make.bat</code> from the repository root on Windows with the .NET SDK and the <a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">64-bit edition of Inno Setup 7</a> installed. The script creates separate publish outputs for x64 and <code>win-arm64</code>, then produces these files in <code>dist/</code>:</p><ul><li><code>Lertaro-Setup.exe</code> and <code>Lertaro-Portable.zip</code> for x64.</li><li><code>Lertaro-Setup-arm64.exe</code> and <code>Lertaro-Portable-arm64.zip</code> for ARM64.</li></ul><p>The application payload in the ARM64 artifacts is native ARM64. The ARM64 installer uses a compatibility Inno Setup bootstrapper, while the x64 installer uses a 64-bit Inno Setup 7 shell. Keep the architecture-specific payload and artifact suffixes aligned with <code>make.bat</code>, <code>Installer/installer.iss</code>, and the release workflow.</p>`,21)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
